local function __jesus_b64decode(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = data:gsub("[^" .. alphabet .. "=]", "")
    local bits = data:gsub(".", function(ch)
        if ch == "=" then return "" end
        local value = alphabet:find(ch, 1, true) - 1
        local out = ""
        for i = 5, 0, -1 do
            out = out .. ((math.floor(value / (2 ^ i)) % 2 == 1) and "1" or "0")
        end
        return out
    end)
    return (bits:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(byte)
        if #byte ~= 8 then return "" end
        local value = 0
        for i = 1, 8 do
            if byte:sub(i, i) == "1" then
                value += 2 ^ (8 - i)
            end
        end
        return string.char(value)
    end))
end

